import * as React from "react";

import { Progress } from "@/registry/erbium/ui/progress";
import { Slider } from "@/registry/erbium/ui/slider";

export const ProgressControlled = () => {
  const [value, setValue] = React.useState(50);

  return (
    <div className="flex w-full max-w-sm flex-col gap-group">
      <Progress value={value} className="w-full" />
      <Slider
        value={value}
        onValueChange={(value) => {
          setValue(value as number);
        }}
        min={0}
        max={100}
        step={1}
      />
    </div>
  );
};

import { ProgressControlled } from "../examples/progress-controlled";

const Example = () => <ProgressControlled />;

export default Example;
